/*
 * seo-inject.mjs — one idempotent pass that gives every sellable page:
 *
 *   1. JSON-LD (@graph: SoftwareApplication + Product) with the real Pro price,
 *      operatingSystem and featureList;
 *   2. assets/shop.js   (live Digiseller lot ids, generated by sync-shop.mjs);
 *   3. assets/preview.js (the 60-second demo pill) and, where missing,
 *      assets/unlock.js (the shared entitlement layer).
 *
 * Run: node tools/seo-inject.mjs
 * It writes only inside the <!-- nov4:seo --> … <!-- /nov4:seo --> markers, so
 * hand edits outside the block survive.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ORIGIN = "https://9xj89gzrtw-hue.github.io";

const OS = "Any (Browser, macOS, Windows, Linux)";

/* The RUB figure in the markup must equal what the cash desk charges, so it
   comes from the generated shop file whenever that lot is live. */
const LIVE = (() => {
  try { return JSON.parse(fs.readFileSync(path.join(ROOT, "data", "shop.json"), "utf8")); }
  catch { return null; }
})();
function liveRub(page) {
  if (!LIVE) return null;
  const entry = page.home
    ? LIVE.bundle
    : LIVE.products && LIVE.products[page.product];
  const rub = entry && Number(entry.price_rub);
  return Number.isFinite(rub) && rub > 0 ? Math.round(rub * 100) / 100 : null;
}

