function ld(page) {
  const a = page.app;  const app = {
    "@type": "SoftwareApplication",
    "@id": `${ORIGIN}${a.url}#app`,
    name: a.name,
    applicationCategory: a.category,
    applicationSubCategory: "Pro license",
    operatingSystem: OS,
    url: `${ORIGIN}${a.url}`,
    description: a.description,
    inLanguage: "ru",
    isAccessibleForFree: true,
    featureList: a.features,
    offers: [
      {
        "@type": "Offer",
        name: "Free",
        price: "0",
        priceCurrency: "USD",
        availability: "https://schema.org/InStock",
        url: `${ORIGIN}${a.url}`
      },
      {
        "@type": "Offer",
        name: "Pro",
        price: String(a.price),
        priceCurrency: "USD",
        availability: "https://schema.org/InStock",
        url: `${ORIGIN}${a.url}`,
        seller: { "@type": "Organization", name: "Toolworks", url: ORIGIN }
      }
    ]
  };
  const product = {
    "@type": "Product",
    "@id": `${ORIGIN}${a.url}#pro`,
    name: `${a.name} — Pro`,
    description: a.description,
    brand: { "@type": "Brand", name: "Toolworks" },
    category: a.category,
    offers: {
      "@type": "Offer",
      price: String(a.price),
      priceCurrency: "USD",
      availability: "https://schema.org/InStock",
      url: `${ORIGIN}${a.url}`,
      seller: { "@type": "Organization", name: "Toolworks", url: ORIGIN }
    }
  };
  const rub = liveRub(page) ?? a.priceRub;
  if (rub) {
    product.offers.alternatePrice = `${rub} RUB`;
  }
  const graph = [app, product];
  if (page.home) {
    graph.push({
      "@type": "ItemList",
      "@id": `${ORIGIN}/#catalog`,
      name: "Toolworks — каталог инструментов",
      numberOfItems: 8,
      itemListElement: PAGES.filter((p) => p.product).map((p, i) => ({
        "@type": "ListItem",
        position: i + 1,
        url: `${ORIGIN}${p.app.url}`,
        name: p.app.name
      }))
    });
  }
  return { "@context": "https://schema.org", "@graph": graph };
}

function block(page, scripts) {
  const tags = scripts
    .map((src) => {
      const attrs = ['src="' + src + '"'];
      if (src.endsWith("preview.js") && (page.product || page.home)) {
        attrs.push(`data-product="${page.product || "all-in-one"}"`);
      }
      if (src.endsWith("preview.js") || src.endsWith("unlock.js")) attrs.push("defer");
      return `  <script ${attrs.join(" ")}></script>`;
    })
    .join("\n");
  const json = JSON.stringify(ld(page), null, 2)
    .split("\n")
    .map((line) => "  " + line)
    .join("\n");
  return [
    "<!-- nov4:seo — generated by tools/seo-inject.mjs -->",
    '  <script type="application/ld+json">',
    json,
    "  </script>",
    tags,
    "  <!-- /nov4:seo -->"
  ].filter(Boolean).join("\n");
}

/* A page that already ships unlock.js (sync, at the end of <body>) must not get
   a second copy: two copies register two click handlers and the second
   `window.Unlock` wins with its own module state. */
function alreadyHas(html, src) {
  const name = src.split("/").pop().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp('src="[^"]*' + name + '"').test(html);
}

let changed = 0;
for (const page of PAGES) {
  const file = path.join(ROOT, page.file);
  let html = fs.readFileSync(file, "utf8");
  html = html.replace(/[ \t]*<!-- nov4:seo[\s\S]*?<!-- \/nov4:seo -->\n?/, "");
  const scripts = page.scripts.filter((src) => !alreadyHas(html, src));
  html = html.replace("</head>", block(page, scripts) + "\n</head>");
  fs.writeFileSync(file, html);
  changed += 1;
}
console.log(`seo-inject: ${changed} pages updated`);
